import com.gymie.groupsession.core.exceptions.GroupSessionIllegalTransitionException
import com.gymie.groupsession.core.services.groupsession.GroupSessionCommandService
import com.gymie.groupsession.core.services.groupsession.GroupSessionQueryService
import io.mockk.clearMocks
import io.mockk.every
import io.mockk.mockk
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.TestConfiguration
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Import
import org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf
import org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.post
import java.time.Instant
import java.util.UUID

/** A refused transition's problem body (KAN-757, decision `transition-codes`): its `code`, and the actor on the "already" codes. */
@WebMvcTest(controllers = [GroupSessionController::class])
@Import(
    GroupSessionController::class,
    GroupSessionExceptionHandler::class,
    GroupSessionTransitionProblemTest.TestConfig::class,
)
class GroupSessionTransitionProblemTest {
    @Autowired lateinit var mockMvc: MockMvc

    @Autowired lateinit var commandService: GroupSessionCommandService

    @Autowired lateinit var queryService: GroupSessionQueryService

    private val viewerId = UUID.fromString("11111111-1111-1111-1111-111111111111")
    private val starterId = UUID.fromString("33333333-3333-3333-3333-333333333333")
    private val sessionId = UUID.randomUUID()
    private val startedAt = Instant.parse("2026-10-07T09:00:00Z")

    @BeforeEach
    fun resetMocks() {
        clearMocks(commandService, queryService)
    }

    @Test
    fun `a refusal carries its code and named actor`() {
        every { queryService.profileOf(starterId) } returns ParticipantProfile(starterId, "Jana Horvat", "jana", null, null)
        every { commandService.start(viewerId, sessionId) } throws
            GroupSessionIllegalTransitionException.alreadyStarted("Cannot start a session that is not planned", started(starterId))

        postStart().andExpect {
            status { isConflict() }
            jsonPath("$.detail") { value("Cannot start a session that is not planned") }
            jsonPath("$.code") { value("session_already_started") }
            jsonPath("$.startedAt") { value("2026-10-07T09:00:00Z") }
            jsonPath("$.startedBy.id") { value(starterId.toString()) }
            jsonPath("$.startedBy.displayName") { value("Jana Horvat") }
        }
    }

    @Test
    fun `an actor from before the migration is null`() {
        every { commandService.start(viewerId, sessionId) } throws
            GroupSessionIllegalTransitionException.alreadyStarted("Cannot start a session that is not planned", started(null))

        postStart().andExpect {
            status { isConflict() }
            jsonPath("$.code") { value("session_already_started") }
            jsonPath("$.startedAt") { value("2026-10-07T09:00:00Z") }
            jsonPath("$.startedBy") { doesNotExist() }
        }
    }

    @Test
    fun `a code without an actor carries no actor properties`() {
        every { commandService.finish(viewerId, sessionId) } throws
            GroupSessionIllegalTransitionException.notStarted("Cannot finish a session that is not in progress")

        mockMvc
            .post("/api/group-sessions/$sessionId/finish") {
                with(user(viewerId.toString()))
                with(csrf())
            }.andExpect {
                status { isConflict() }
                jsonPath("$.code") { value("session_not_started") }
                jsonPath("$.startedBy") { doesNotExist() }
                jsonPath("$.finishedBy") { doesNotExist() }
                jsonPath("$.startedAt") { doesNotExist() }
                jsonPath("$.finishedAt") { doesNotExist() }
            }
    }

    private fun started(by: UUID?) = GroupSessionLifecycle(GroupSessionStatus.IN_PROGRESS, startedAt = startedAt, startedBy = by)

    private fun postStart() =
        mockMvc.post("/api/group-sessions/$sessionId/start") {
            with(user(viewerId.toString()))
            with(csrf())
        }

    @TestConfiguration
    class TestConfig {
        @Bean
        fun groupSessionCommandService(): GroupSessionCommandService = mockk()

        @Bean
        fun groupSessionQueryService(): GroupSessionQueryService = mockk()
    }
}
