            workoutFinishReadinessService.finishReadiness(userId, resolve(authentication, id, userId)),
        )

    /**
     * The workout id for [userId] within group session [id], resolved through the session's own
     * access rules — never named by the client. Refuses a `VIEW` viewer with
     * [com.gymie.groupsession.core.exceptions.GroupSessionForbiddenException] (403
     * `edit_access_required`), and a non-participant caller, non-participant [userId] or missing
     * session with [com.gymie.groupsession.core.exceptions.GroupSessionNotFoundException] (404).
     */
    private fun resolve(
        authentication: Authentication,
        id: UUID,
        userId: UUID,
    ): UUID = groupSessionQueryService.participantWorkoutId(UUID.fromString(authentication.name), id, userId)

    /**
     * As [resolve], plus the live-grant check (design § 4): a participant who has lowered or revoked the
     * owner's `WORKOUTS: EDIT` grant mid-session answers `403` on every write route from here on, even
     * though [resolve] would still find the row.
     */
    private fun resolveForWrite(
        authentication: Authentication,
        id: UUID,
        userId: UUID,
    ): UUID = groupSessionQueryService.participantWorkoutIdForWrite(UUID.fromString(authentication.name), id, userId)
}

